import 'package:font_asset/font_asset.dart';
import 'package:hooks/hooks.dart';

/// Provides the `RobotoFromHook` font family to the app.
///
/// The font files are taken from the Flutter SDK cache (the repository does not
/// contain binaries), relative to this package. In a real package the fonts
/// would ship with the package or be generated by the hook.
void main(List<String> arguments) async {
  await build(arguments, (BuildInput input, BuildOutputBuilder output) async {
    const materialFonts = '../../../bin/cache/artifacts/material_fonts';
    addFontFamily(
      input,
      output,
      family: 'RobotoFromHook',
      fonts: const <FontFile>[
        FontFile('$materialFonts/Roboto-Regular.ttf', name: 'fonts/Roboto-Regular.ttf'),
        FontFile('$materialFonts/Roboto-Bold.ttf', name: 'fonts/Roboto-Bold.ttf', weight: 700),
      ],
    );
  });
}
